tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/3c-entry-subtraction-free-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: not worktree"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e bench/variations/stage7-3c-entry-world-only.json -e scripts/ringer/stage7/3c_entry_replay_probe.py -e tests/test_3c_entry_subtraction.py)
test -z "$bad" || { echo "FAIL: outside ownership: $bad"; exit 1; }
git diff --quiet -- storygame data || { echo "FAIL: storygame/data edited"; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_3c_entry_subtraction.py tests/test_knowledge_projection.py tests/test_3c_cue_chain.py tests/test_markdown_story_package.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
rm -rf /tmp/entry-replay-dry; $PY scripts/ringer/stage7/3c_entry_replay_probe.py --rows bench/results/stage7-3c-escape-close-smoke/rows.json --samples 12 --dry --out /tmp/entry-replay-dry || exit 1
test -s /tmp/entry-replay-dry/subtraction.user.txt || { echo "FAIL: no subtraction prompt"; exit 1; }
diff /tmp/entry-replay-dry/control.user.txt /tmp/entry-replay-dry/subtraction.user.txt | grep -c '^<' | grep -qx 1 || { echo "FAIL: diff is not exactly one removed line"; exit 1; }
diff /tmp/entry-replay-dry/control.user.txt /tmp/entry-replay-dry/subtraction.user.txt | grep -c '^>' | grep -qx 0 || { echo "FAIL: lines added"; exit 1; }
$PY -m ruff check scripts/ringer/stage7/3c_entry_replay_probe.py tests/test_3c_entry_subtraction.py && $PY -m ruff format --check scripts/ringer/stage7/3c_entry_replay_probe.py tests/test_3c_entry_subtraction.py || exit 1
git add -A -- scripts tests bench/variations && git diff --cached -- scripts tests bench/variations > /home/bcorfman/dev/ringer-work/3c-entry-subtraction-free.patch && test -s /home/bcorfman/dev/ringer-work/3c-entry-subtraction-free.patch && echo "patch exported"
